"""Precommitted request-only replay against independently supplied expert phases.

Prepare uses only composition/temperature metadata. Evaluate refuses to open
measurements or labels without an externally retrievable public bundle receipt.
The policy subprocess receives only coordinates and queried XRD patterns.
"""
from pathlib import Path
import argparse
import datetime
import hashlib
import io
import json
import os
import subprocess
import sys
import urllib.request
import zipfile
import xml.etree.ElementTree as ET
import numpy as np
from scipy.optimize import milp, Bounds, LinearConstraint
from scipy.spatial.distance import cdist

ROOT = Path(__file__).resolve().parents[1]
LOCK = ROOT/'protocols/public_phase_trial'
RAW = ROOT/'data/raw/public_phase_trial'
DEST = ROOT/'results/public_phase_trial'
NS={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def canonical(obj):
    return json.dumps(obj,sort_keys=True,separators=(',',':'),allow_nan=False).encode()

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def write_json(path,obj):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps(obj,indent=2,allow_nan=False)+'\n')

def protocol():return json.loads((LOCK/'protocol.json').read_text())

def prepare():
    assert not (LOCK/'public_receipt.json').exists()
    assert not (DEST/'first_outcome_access.json').exists()
    p=protocol();g=json.loads((LOCK/'geometry.json').read_text())
    n=len(g['normalized_coordinates']);pairs=np.asarray(g['neighbourhoods'],int)
    incidence=np.zeros((len(pairs),n));incidence[np.arange(len(pairs))[:,None],pairs]=1
    g['coordinates']=g['normalized_coordinates'];g['initializations']={}
    for seed in p['seeds']:
        initial=[g['reference_action']]
        candidates=np.setdiff1d(np.arange(n),initial)
        initial+=np.random.default_rng(seed).choice(candidates,3,replace=False).tolist()
        lower=np.zeros(n);lower[initial]=1
        result=milp(np.ones(n),integrality=np.ones(n),bounds=Bounds(lower,np.ones(n)),
                    constraints=LinearConstraint(incidence,np.ones(len(pairs)),np.full(len(pairs),np.inf)),
                    options={'time_limit':60,'mip_rel_gap':0})
        if result.success:
            rescue=np.flatnonzero(result.x>.5).tolist()
            assert np.isin(pairs,rescue).any(1).all()
            cover={'status':'optimal','minimum_total_if_optimal':len(rescue),'rescue':rescue,
                   'solver_reported_gap':float(result.mip_gap),'solver_dual_bound':float(result.mip_dual_bound)}
        else:cover={'status':'cover_failed','solver_message':str(result.message)}
        g['initializations'][str(seed)]={'initial':initial,'cover':cover}
    write_json(LOCK/'geometry.json',g)
    print(json.dumps({'metadata_actions':n,'declared_pairs':len(pairs),
                     'cover_totals':[v['cover'].get('minimum_total_if_optimal') for v in g['initializations'].values()]}))

def verify_registration():
    receipt=json.loads((LOCK/'public_receipt.json').read_text())
    bundle_path=LOCK/'preregistration_bundle.json'
    assert digest(bundle_path)==receipt['bundle_sha256']
    bundle=json.loads(bundle_path.read_text())
    for rel,item in bundle['files'].items():
        assert digest(ROOT/rel)==item['sha256'],rel
    # Public receipt is an observation of GitHub publication, not an assertion
    # of an independent data custodian or an authenticated timestamp authority.
    assert receipt['public_retrieval_verified'] is True
    return receipt

def xlsx_rows(path):
    with zipfile.ZipFile(path) as z:
        strings=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            for item in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',NS):
                strings.append(''.join(t.text or '' for t in item.iterfind('.//s:t',NS)))
        sheets=sorted(name for name in z.namelist() if name.startswith('xl/worksheets/sheet') and name.endswith('.xml'))
        for name in sheets:
            rows=[]
            for row in ET.fromstring(z.read(name)).findall('.//s:sheetData/s:row',NS):
                out={}
                for c in row.findall('s:c',NS):
                    col=''.join(t for t in c.attrib['r'] if t.isalpha())
                    v=c.find('s:v',NS)
                    value=v.text if v is not None else ''
                    if c.attrib.get('t')=='s':value=strings[int(value)] if value else ''
                    if c.attrib.get('t')=='inlineStr':value=''.join(t.text or '' for t in c.iterfind('.//s:t',NS))
                    out[col]=value
                rows.append(out)
            yield rows

def numeric_matrix(path):
    # CombiView's prose and blank header lines precede a rectangular numerical
    # block. All block rows must be retained; no intensity-dependent filtering.
    rows=[]
    for line in path.read_bytes().decode('cp1252').splitlines():
        parts=line.split('\t')
        try:row=[float(t) for t in parts]
        except ValueError:continue
        if len(row)>10:rows.append(row)
    assert rows and len({len(row) for row in rows})==1,'Unrecognized rectangular CombiView block'
    return np.asarray(rows,float)

def load_outcomes():
    receipt=verify_registration();p=protocol();g=json.loads((LOCK/'geometry.json').read_text())
    marker=DEST/'first_outcome_access.json'
    if not marker.exists():
        with marker.open('x') as stream:
            json.dump({'first_quantitative_access_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
                       'public_commit':receipt['commit_sha'],'bundle_sha256':receipt['bundle_sha256'],
                       'scope':'First numerical use of XRD and expert annotations; source methods and covariates were inspected earlier'},stream,indent=2)
    n_full=p['source_full_patterns'];selected=np.asarray(g['source_indices'],int)
    matrix=numeric_matrix(RAW/'diffraction.txt')
    # The released block may have an explicit action/axis index column. Shape
    # decides its removal, never an acquisition result or prediction score.
    if matrix.shape[0]==n_full+1:
        if np.array_equal(matrix[:,0],np.arange(n_full+1)) or np.array_equal(matrix[:,0],np.arange(-1,n_full)):
            matrix=matrix[:,1:]
        axis=matrix[0];full=matrix[1:]
    elif matrix.shape[1] in [n_full+1,n_full+2]:
        if matrix.shape[1]==n_full+2:matrix=matrix[:,1:]
        axis=matrix[:,0];full=matrix[:,1:].T
    else:raise ValueError('CombiView numerical block shape is not the predeclared physical grid')
    assert full.shape[0]==n_full and len(axis)==full.shape[1]
    assert np.all(np.isfinite(full)) and np.all(np.linalg.norm(full,axis=1)>0)
    votes=np.full((len(selected),5),-1,int)
    wanted={(round(float(nb),6),round(float(t),6)):i for i,(nb,t) in enumerate(g['physical_coordinates'])}
    matched=0;annotation_source=None
    for path in sorted(RAW.glob('labels_*.xlsx')):
        for rows in xlsx_rows(path):
            if not rows:continue
            header={v:k for k,v in rows[0].items()}
            if not all(t in header for t in ['V','temp','HL1','HL2','HL3','HL4','HL5']):continue
            assert annotation_source is None,'Ambiguous expert-label workbook'
            annotation_source=path.name
            for row in rows[1:]:
                if not row.get(header['V']) or not row.get(header['temp']):continue
                v=float(row[header['V']]);v=v/100 if v>1 else v
                key=(round(1-v,6),round(float(row[header['temp']]),6))
                if key not in wanted:continue
                idx=wanted[key]
                assert np.all(votes[idx]==-1),'Duplicate composition/temperature annotation'
                for j,name in enumerate(['HL1','HL2','HL3','HL4','HL5']):
                    value=row.get(header[name],'')
                    if value!='':votes[idx,j]=int(float(value))
                matched+=1
    assert annotation_source is not None and matched==len(selected),'Missing independent phase annotations'
    assert set(np.unique(votes)) <= {-1,0,1,2}
    y=full[selected]
    np.savez_compressed(DEST/'physical_field_and_expert_labels.npz',outcomes=y,axis=axis,votes=votes)
    identity={'source_full_patterns':n_full,'included_patterns':len(y),'channels':y.shape[1],
              'annotation_source':annotation_source,'matched_expert_annotation_rows':matched,
              'raw_file_hashes':{f.name:digest(f) for f in sorted(RAW.iterdir()) if f.is_file()},
              'raw_vectors_unchanged':True,'expert_labels_not_generated_by_us':True,
              'no_injection_interpolation_noise_draw':True}
    write_json(DEST/'measurement_identity.json',identity)
    return y,votes

def request(proc,message):
    proc.stdin.write(json.dumps(message,allow_nan=False)+'\n');proc.stdin.flush()
    line=proc.stdout.readline()
    if not line:raise RuntimeError(proc.stderr.read())
    return json.loads(line)

def acquire(g,y,seed,budget,policy,guarded,altered=False):
    p=protocol();init=g['initializations'][str(seed)];cover=init['cover']
    record={'seed':seed,'budget':budget,'policy':policy,'guarded':guarded,'initial':init['initial'],
            'cover_total':cover.get('minimum_total_if_optimal')}
    if guarded and (cover['status']!='optimal' or cover['minimum_total_if_optimal']>budget):
        record['status']='budget_failed' if cover['status']=='optimal' else 'cover_failed';return record
    config={'domain':'phase','coordinates':g['coordinates'],'seed':seed,'budget':budget,'policy':policy,
            'guarded':guarded,'rescue':cover['rescue'],'length_scale':p['kernel_length_scale'],
            'noise_variance':p['working_noise_variance']}
    proc=subprocess.Popen([sys.executable,'-I',str(ROOT/'src/locked_replay_policy.py')],stdin=subprocess.PIPE,
                          stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,bufsize=1,
                          cwd=LOCK,env={**os.environ,'OPENBLAS_NUM_THREADS':'1'})
    actions=[];trace=[]
    try:
        request(proc,{'op':'initialize','config':config})
        for t in range(budget):
            info={'action':init['initial'][t],'initial':True} if t<len(init['initial']) else {**request(proc,{'op':'propose'}),'initial':False}
            a=info['action'];assert a not in actions
            value=y[a].tolist();request(proc,{'op':'observe','action':a,'outcome':value})
            actions.append(a);trace.append({**info,'outcome_sha256':hashlib.sha256(canonical(value)).hexdigest()})
        final=request(proc,{'op':'finish'})
        if guarded:assert final['rescue_remaining']==0
        record.update(status='completed',actions=actions,trace=trace,final_trace_fraction=final['trace_fraction'],
                      overrides=sum(t.get('override',False) for t in trace))
    finally:
        proc.stdin.close();proc.wait(timeout=20)
        if proc.returncode:raise RuntimeError(proc.stderr.read())
        proc.stdout.close();proc.stderr.close()
    return record

def expert_classes(votes,quorum):
    counts=np.asarray([(votes==label).sum(1) for label in range(3)]).T
    winner=np.argmax(counts,axis=1);valid=counts.max(1)>=quorum
    return winner,valid,counts

def score(record,g,y,votes):
    if record['status']!='completed':return {}
    p=protocol();pairs=np.asarray(g['neighbourhoods']);sel=record['actions'];hit=np.isin(pairs,sel).any(1)
    cls,valid,counts=expert_classes(votes,p['expert_quorum']);ref=g['reference_action']
    same=cls[pairs[:,0]]==cls[pairs[:,1]]
    eligible=valid[pairs].all(1)&same&(cls[pairs[:,0]]!=cls[ref]) if valid[ref] else np.zeros(len(pairs),bool)
    total=int(eligible.sum());observed=eligible&hit
    normalized=y/np.linalg.norm(y,axis=1)[:,None];x=np.asarray(g['coordinates'])
    K=np.exp(-cdist(x,x,'sqeuclidean')/(2*p['kernel_length_scale']**2))
    pred=K[:,sel]@np.linalg.solve(K[np.ix_(sel,sel)]+p['working_noise_variance']*np.eye(len(sel)),normalized[sel])
    metrics={'primary_status':'assessable' if total and valid[ref] else 'not_assessable',
             'primary_cores':total,'primary_core_capture':float(observed.sum()/total) if total else None,
             'primary_cores_missed':int((eligible&~hit).sum()),'primary_missed_core_ids':np.flatnonzero(eligible&~hit).tolist(),
             'reference_phase_code':int(cls[ref]) if valid[ref] else None,'reference_votes':votes[ref].tolist(),
             'phase_codes_observed':sorted(set(cls[sel][valid[sel]].tolist())),
             'opportunity_coverage':float(hit.mean()),'opportunity_all':bool(hit.all()),
             'normalized_reconstruction_mse':float(np.sum((normalized-pred)**2)/np.sum(normalized**2)),
             'working_uncertainty_reduction':float(1-record['final_trace_fraction']),
             'physical_power_status':'unverified_calibration','population_power':None,'population_p_value':None,
             'phase_strata':{},'consensus_sensitivity':{}}
    for phase in range(3):
        use=valid[pairs].all(1)&same&(cls[pairs[:,0]]==phase)
        metrics['phase_strata'][str(phase)]={'cores':int(use.sum()),'capture':float(hit[use].mean()) if use.any() else None}
    for quorum in [3,5]:
        c,v,_=expert_classes(votes,quorum)
        use=v[pairs].all(1)&(c[pairs[:,0]]==c[pairs[:,1]])&(c[pairs[:,0]]!=c[ref]) if v[ref] else np.zeros(len(pairs),bool)
        metrics['consensus_sensitivity'][str(quorum)]={'cores':int(use.sum()),'capture':float(hit[use].mean()) if use.any() else None}
    return metrics

def aggregate(records):
    p=protocol();table=[]
    for policy in p['policies']:
        for guarded in [False,True]:
            rows=[r for r in records if r['policy']==policy and r['guarded']==guarded and r['budget']==p['primary_budget']]
            valid=[r for r in rows if r['status']=='completed']
            row={'policy':policy,'guarded':guarded,'completed':len(valid),'failed':len(rows)-len(valid)}
            for name in ['primary_core_capture','opportunity_coverage','normalized_reconstruction_mse','working_uncertainty_reduction']:
                values=[r['metrics'][name] for r in valid if r['metrics'].get(name) is not None]
                row['median_'+name]=float(np.median(values)) if values else None
            row['all_primary_cores_captured_runs']=sum(r['metrics']['primary_status']=='assessable' and r['metrics']['primary_cores_missed']==0 for r in valid)
            row['median_overrides']=float(np.median([r['overrides'] for r in valid])) if valid else None
            if guarded:
                changes=[]
                for r in valid:
                    base=next(q for q in records if q['seed']==r['seed'] and q['budget']==r['budget'] and q['policy']==policy and not q['guarded'])
                    changes.append(r['metrics']['normalized_reconstruction_mse']/base['metrics']['normalized_reconstruction_mse']-1)
                row['paired_median_mse_change']=float(np.median(changes)) if changes else None
            table.append(row)
    return {'version':p['version'],'records':len(records),'completed':sum(r['status']=='completed' for r in records),
            'failures':sum(r['status']!='completed' for r in records),'primary_table':table,
            'scope':'One frozen field, external expert-consensus annotations; repeat policy initializations are not independent physical specimens',
            'physical_power':'unverified_calibration','labels_visible_to_planner':False}

def evaluate():
    verify_registration();y,votes=load_outcomes();g=json.loads((LOCK/'geometry.json').read_text());p=protocol()
    records=[]
    with (DEST/'acquisition_trajectories.jsonl').open('w') as stream:
        for seed in p['seeds']:
            for budget in p['budgets']:
                for policy in p['policies']:
                    for guarded in [False,True]:
                        r=acquire(g,y,seed,budget,policy,guarded);records.append(r);stream.write(json.dumps(r,allow_nan=False)+'\n')
            print(f'Frozen acquisition seed={seed}: {len(records)} records',flush=True)
    # The expert labels are loaded only in the oracle/evaluator process and are
    # used for these endpoints after the entire acquisition suite is complete.
    for record in records:record['metrics']=score(record,g,y,votes)
    with (DEST/'evaluated_records.jsonl').open('w') as stream:
        for r in records:stream.write(json.dumps(r,allow_nan=False)+'\n')
    summary=aggregate(records);write_json(DEST/'summary.json',summary)
    print(json.dumps({'records':len(records),'failures':summary['failures'],'physical_power':summary['physical_power']}))

if __name__=='__main__':
    arg=argparse.ArgumentParser();arg.add_argument('operation',choices=['prepare','evaluate']);a=arg.parse_args()
    prepare() if a.operation=='prepare' else evaluate()
